# region: fold
def fold(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: gather
def gather(xs):
    return [v for v in xs if v % 2 == 0]

# region: intake
def intake(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: emit
def emit(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return emit(intake(gather(fold(raw))))

